import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with 'http' or 'https'
    if not url.lower().startswith('https'):
        return False

    # Check for user info in the URL
    if '@' in url.split('//')[1]:
        return False

    # Check for invalid characters in the URL
    if any(ord(char) <= 31 or ord(char) == 127 for char in url):
        return False

    # Extract the host part of the URL
    host = url.split('//')[1].split('/')[0]

    # Check if the host ends with '.'
    if host.endswith('.'):
        return False

    # Split the host by '.' and validate each label
    labels = host.split('.')
    if len(labels) < 2 or labels[-1] == '':
        return False
    for label in labels[:-1]:
        if not re.match(r'^[a-z0-9-]+$', label):
            return False
    if not re.match(r'^[a-z]+$', labels[-1]):
        return False

    # Check if the host is 'localhost' or ends with '.localhost'
    if host.lower() in ['localhost', 'localhost.']:
        return False

    # Check if there is a port specified and it is not 443
    if ':' in host and int(host.split(':')[1]) != 443:
        return False

    return True
